#include <cstdint>
#include <cstdio>
#include <iostream>
#include <sstream>
#include <string>

// The solution file defines this struct identically; the layout must match.
struct Parser
{
    std::uint8_t state;
    std::uint8_t expected;
    std::uint8_t received;
    std::uint8_t sum;
    std::uint8_t payload[16];
    std::uint8_t guard[4];
};

int Feed(Parser& p, std::uint8_t byte);

static bool guardIntact(const Parser& p)
{
    for (int i = 0; i < 4; i++)
    {
        if (p.guard[i] != 0xA5) { return false; }
    }
    return true;
}

int main()
{
    std::string line;
    while (std::getline(std::cin, line))
    {
        Parser p = {};
        for (int i = 0; i < 4; i++) { p.guard[i] = 0xA5; }

        std::istringstream in(line);
        unsigned b;
        int frames = 0;
        bool overrun = false;
        while (in >> std::hex >> b)
        {
            int len = Feed(p, static_cast<std::uint8_t>(b));
            if (!guardIntact(p) && !overrun)
            {
                overrun = true;
                std::printf("OVERRUN\n");
            }
            if (len > 0 && len <= 16)
            {
                frames++;
                std::printf("frame:");
                for (int i = 0; i < len; i++) { std::printf(" %02x", p.payload[i]); }
                std::printf("\n");
            }
            else if (len != 0)
            {
                std::printf("bad length %d\n", len);
            }
        }
        if (frames == 0 && !overrun) { std::printf("none\n"); }
        std::printf("--\n");
    }
    return 0;
}

