"""Random byte streams: noise, valid frames (with correct checksums), frames
with a wrong checksum, and frames with an out-of-range length."""


def _frame(rng, length=None, bad_checksum=False):
    n = length if length is not None else rng.randint(1, 16)
    payload = [rng.choice([0xAA, rng.randint(0, 255)]) for _ in range(n)]
    checksum = (-sum(payload)) & 0xFF
    if bad_checksum:
        checksum = (checksum + rng.randint(1, 255)) & 0xFF
    return [0xAA, n] + payload + [checksum]


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    stream = []
    for _ in range(rng.randint(2, 5)):
        stream += [rng.choice([0x00, 0x55, 0xFF, 0x7E]) for _ in range(rng.randint(0, 3))]
        kind = rng.random()
        if kind < 0.6:
            stream += _frame(rng)
        elif kind < 0.8:
            stream += _frame(rng, bad_checksum=True)
        else:
            stream += [0xAA, rng.choice([0, 17, 40, 255])]
    return {"name": "a noisy stream of %d bytes #%d" % (len(stream), index),
            "stdin": " ".join("%02x" % b for b in stream) + "\n"}
